"""Workflow analysis tools.

Load, analyze, summarize, and validate ComfyUI workflow JSON.
Handles both UI format (from ComfyUI "Save") and API format
(from "Save API Format" or programmatic use).

These tools give the agent deep understanding of what a workflow does,
what's connected to what, and what can be safely modified.
"""

import json
from pathlib import Path

import httpx

from ._util import to_json
from ..config import COMFYUI_URL

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "load_workflow",
        "description": (
            "Load and analyze a ComfyUI workflow JSON file. "
            "Returns: format type, all nodes with class_type, "
            "connections between nodes (the graph), editable fields "
            "with current values, and a human-readable summary of the pipeline. "
            "This is the main tool for understanding what a workflow does."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "validate_workflow",
        "description": (
            "Validate a workflow against the running ComfyUI instance. "
            "Checks that all node types exist (are installed), that required "
            "inputs are provided, and that connections have compatible types. "
            "Requires ComfyUI to be running."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "get_editable_fields",
        "description": (
            "Get a focused list of all editable fields in a workflow — "
            "the parameters that can be changed without rewiring the graph. "
            "Groups fields by node class_type for easy scanning. "
            "This is useful before modifying a workflow."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
                "class_filter": {
                    "type": "string",
                    "description": (
                        "Optional: only show fields from nodes matching this "
                        "class_type substring (case-insensitive)."
                    ),
                },
            },
            "required": ["path"],
        },
    },
]

# ---------------------------------------------------------------------------
# Core parsing logic
# ---------------------------------------------------------------------------


def _load_json(path_str: str) -> tuple[dict, str | None]:
    """Load JSON from file. Returns (data, error_or_none)."""
    path = Path(path_str)
    if not path.exists():
        return {}, f"File not found: {path_str}"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data, None
    except json.JSONDecodeError as e:
        return {}, f"Invalid JSON: {e}"


def _extract_api_format(data: dict) -> tuple[dict, str]:
    """
    Extract API-format node dict from any workflow format.

    Returns (api_nodes, format_name).
    api_nodes: {node_id_str: {"class_type": ..., "inputs": {...}}}
    """
    # Check for UI format (has "nodes" array)
    if "nodes" in data and isinstance(data["nodes"], list):
        # Prefer embedded API format in extra.prompt
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            return nodes, "ui_with_api"

        # UI-only: convert nodes array
        nodes = {}
        for node in data["nodes"]:
            nid = str(node.get("id", ""))
            class_type = node.get("type", "Unknown")
            widgets = node.get("widgets_values", [])
            nodes[nid] = {
                "class_type": class_type,
                "inputs": {},
                "_widgets_values": widgets,
                "_ui_node": True,
            }
        return nodes, "ui_only"

    # API format: top-level keys are node IDs
    nodes = {
        k: v for k, v in data.items()
        if isinstance(v, dict) and "class_type" in v
    }
    return nodes, "api"


def _trace_connections(nodes: dict) -> list[dict]:
    """
    Trace connections between nodes.

    In API format, a connection is an input value that's a list:
    [source_node_id_str, output_index_int]

    Returns list of connection dicts.
    """
    connections = []
    for target_id, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue  # UI-only nodes don't have connection info
        for input_name, value in sorted(node.get("inputs", {}).items()):
            if isinstance(value, list) and len(value) == 2:
                source_id = str(value[0])
                output_idx = value[1]
                source_class = nodes.get(source_id, {}).get("class_type", "?")
                target_class = node.get("class_type", "?")
                connections.append({
                    "from_node": source_id,
                    "from_class": source_class,
                    "from_output": output_idx,
                    "to_node": target_id,
                    "to_class": target_class,
                    "to_input": input_name,
                })
    return connections


def _find_editable_fields(nodes: dict, class_filter: str = "") -> list[dict]:
    """
    Find all non-connection input fields (the editable parameters).
    """
    fields = []
    filter_lower = class_filter.lower()

    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")
        if filter_lower and filter_lower not in class_type.lower():
            continue

        # He2025: sort for deterministic field order per node
        for field_name, value in sorted(node.get("inputs", {}).items()):
            # Skip connections (2-element list [node_id, output_index])
            if isinstance(value, list) and len(value) == 2:
                continue

            fields.append({
                "node_id": nid,
                "class_type": class_type,
                "field": field_name,
                "value": value,
                "type": type(value).__name__,
            })

    return fields


def _build_summary(nodes: dict, connections: list[dict], fmt: str) -> str:
    """Build a human-readable summary of the workflow pipeline."""
    if not nodes:
        return "Empty workflow (no nodes found)."

    lines = []

    # Class type counts
    class_counts: dict[str, int] = {}
    for node in nodes.values():
        ct = node.get("class_type", "Unknown")
        class_counts[ct] = class_counts.get(ct, 0) + 1

    lines.append(f"{len(nodes)} nodes, {len(connections)} connections")
    lines.append("")

    # Identify pipeline stages by looking at node classes
    loaders = []
    encoders = []
    samplers = []
    outputs = []
    other = []

    for ct in sorted(class_counts.keys()):
        ct_lower = ct.lower()
        if any(k in ct_lower for k in ("load", "checkpoint", "unet", "model")):
            loaders.append(ct)
        elif any(k in ct_lower for k in ("encode", "clip", "conditioning")):
            encoders.append(ct)
        elif any(k in ct_lower for k in ("sample", "sampler", "ksampler", "denoise")):
            samplers.append(ct)
        elif any(k in ct_lower for k in ("save", "preview", "output", "combine", "video")):
            outputs.append(ct)
        else:
            other.append(ct)

    if loaders:
        lines.append(f"Loaders: {', '.join(loaders)}")
    if encoders:
        lines.append(f"Encoding: {', '.join(encoders)}")
    if samplers:
        lines.append(f"Sampling: {', '.join(samplers)}")
    if outputs:
        lines.append(f"Output: {', '.join(outputs)}")
    if other:
        lines.append(f"Other: {', '.join(other)}")

    # Describe data flow from connections
    if connections:
        lines.append("")
        lines.append("Data flow:")
        # Group by target node to show input sources
        by_target: dict[str, list[dict]] = {}
        for conn in connections:
            key = f"{conn['to_node']} ({conn['to_class']})"
            by_target.setdefault(key, []).append(conn)

        for target, conns in sorted(by_target.items()):
            sources = [f"{c['from_class']}.out[{c['from_output']}]" for c in conns]
            lines.append(f"  {target} <- {', '.join(sources)}")

    if fmt == "ui_only":
        lines.append("")
        lines.append(
            "Note: UI-only format — editable field values not available. "
            "Use an API-format workflow for full analysis."
        )

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Validation (requires live ComfyUI)
# ---------------------------------------------------------------------------

def _validate_against_comfyui(nodes: dict, connections: list[dict]) -> dict:
    """Validate workflow against running ComfyUI instance."""
    errors = []
    warnings = []

    # Fetch all node info
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}/object_info", timeout=30.0)
            resp.raise_for_status()
            all_info = resp.json()
    except httpx.ConnectError:
        return {"error": f"ComfyUI not reachable at {COMFYUI_URL}. Is it running?"}
    except Exception as e:
        return {"error": str(e)}

    # Check each node
    # He2025: sort for deterministic error order
    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")

        # Check node type exists
        if class_type not in all_info:
            errors.append(f"Node [{nid}]: class_type '{class_type}' not installed.")
            continue

        node_schema = all_info[class_type]
        required_inputs = node_schema.get("input", {}).get("required", {})
        optional_inputs = node_schema.get("input", {}).get("optional", {})
        all_known_inputs = {**required_inputs, **optional_inputs}

        # Check required inputs are provided
        node_inputs = node.get("inputs", {})
        for req_name in required_inputs:
            if req_name not in node_inputs:
                errors.append(
                    f"Node [{nid}] {class_type}: missing required input '{req_name}'."
                )

        # Check for unknown inputs
        for inp_name in node_inputs:
            if inp_name not in all_known_inputs:
                warnings.append(
                    f"Node [{nid}] {class_type}: unknown input '{inp_name}' "
                    f"(may be from a different version)."
                )

    # Check connection type compatibility
    for conn in connections:
        source_class = conn["from_class"]
        output_idx = conn["from_output"]
        target_class = conn["to_class"]
        target_input = conn["to_input"]

        # Get source output types
        source_info = all_info.get(source_class, {})
        source_outputs = source_info.get("output", [])
        if output_idx < len(source_outputs):
            source_type = source_outputs[output_idx]
        else:
            errors.append(
                f"Connection {source_class}[{output_idx}] → "
                f"{target_class}.{target_input}: output index out of range."
            )
            continue

        # Get target input type
        target_info = all_info.get(target_class, {})
        all_target_inputs = {
            **target_info.get("input", {}).get("required", {}),
            **target_info.get("input", {}).get("optional", {}),
        }
        target_spec = all_target_inputs.get(target_input)
        if target_spec and isinstance(target_spec, (list, tuple)) and len(target_spec) > 0:
            target_type = target_spec[0]
            # Check type compatibility (exact match or wildcard "*")
            if (
                isinstance(target_type, str)
                and isinstance(source_type, str)
                and target_type != "*"
                and source_type != "*"
                and source_type != target_type
            ):
                errors.append(
                    f"Type mismatch: {source_class}.out[{output_idx}] "
                    f"({source_type}) → {target_class}.{target_input} "
                    f"(expects {target_type})."
                )

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
    }


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_load_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    connections = _trace_connections(nodes)
    editable = _find_editable_fields(nodes)
    summary = _build_summary(nodes, connections, fmt)

    # Build node list for output
    node_list = {}
    for nid, node in nodes.items():
        entry = {
            "class_type": node.get("class_type", ""),
        }
        if not node.get("_ui_node"):
            entry["input_count"] = len(node.get("inputs", {}))
        node_list[nid] = entry

    return to_json({
        "file": path_str,
        "format": fmt,
        "node_count": len(nodes),
        "connection_count": len(connections),
        "editable_field_count": len(editable),
        "summary": summary,
        "nodes": node_list,
        "connections": connections,
        "editable_fields": editable,
    })


def _handle_validate_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only workflow format — can't validate without API format data. "
                "Re-export the workflow using 'Save (API Format)' in ComfyUI, "
                "or use a workflow that has extra.prompt embedded."
            ),
        })

    connections = _trace_connections(nodes)
    result = _validate_against_comfyui(nodes, connections)
    return to_json(result)


def _handle_get_editable_fields(tool_input: dict) -> str:
    path_str = tool_input["path"]
    class_filter = tool_input.get("class_filter", "")

    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only format — field values aren't available. "
                "Use an API-format workflow or one with extra.prompt embedded."
            ),
        })

    fields = _find_editable_fields(nodes, class_filter)

    # Group by class_type for readability
    by_class: dict[str, list[dict]] = {}
    for f in fields:
        by_class.setdefault(f["class_type"], []).append(f)

    return to_json({
        "file": path_str,
        "total_fields": len(fields),
        "fields_by_class": by_class,
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a workflow_parse tool call."""
    try:
        if name == "load_workflow":
            return _handle_load_workflow(tool_input)
        elif name == "validate_workflow":
            return _handle_validate_workflow(tool_input)
        elif name == "get_editable_fields":
            return _handle_get_editable_fields(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except Exception as e:
        return to_json({"error": str(e)})

"""ComfyUI HTTP API tools.

Wraps the ComfyUI REST API as Agent SDK tools so the agent can
query the running ComfyUI instance for node info, system stats,
queue status, and execution history.
"""

import httpx

from ..circuit_breaker import COMFYUI_BREAKER
from ..config import COMFYUI_URL
from ._util import to_json

# ---------------------------------------------------------------------------
# Tool schemas (Anthropic tool-use format)
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "is_comfyui_running",
        "description": (
            "Check if ComfyUI is running and reachable. "
            "Call this first before using other ComfyUI tools."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_all_nodes",
        "description": (
            "Get registered node types in ComfyUI via GET /object_info. "
            "Use format='names_only' (just class_type names) or "
            "'summary' (name+category) to control response size. "
            "Use 'full' for complete input/output schemas. "
            "Prefer get_node_info for a specific node."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "category_filter": {
                    "type": "string",
                    "description": (
                        "Optional substring to filter nodes by category "
                        "(e.g. 'sampling', 'loaders', 'image'). "
                        "Case-insensitive."
                    ),
                },
                "name_filter": {
                    "type": "string",
                    "description": (
                        "Optional substring to filter nodes by class_type name "
                        "(e.g. 'KSampler', 'ControlNet'). Case-insensitive."
                    ),
                },
                "format": {
                    "type": "string",
                    "enum": ["names_only", "summary", "full"],
                    "description": (
                        "Response format. 'names_only': just class_type names (smallest). "
                        "'summary': name + category + display_name (default). "
                        "'full': includes input types and output types."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "get_node_info",
        "description": (
            "Get detailed info for a specific ComfyUI node type: "
            "its required/optional inputs with types and defaults, "
            "output types, category, and description. "
            "Use the exact class_type name (e.g. 'KSampler', 'CLIPTextEncode')."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "node_type": {
                    "type": "string",
                    "description": "Exact class_type name of the node.",
                },
            },
            "required": ["node_type"],
        },
    },
    {
        "name": "get_system_stats",
        "description": (
            "Get ComfyUI system stats: GPU info, VRAM usage, "
            "Python version, and currently loaded models."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_queue_status",
        "description": (
            "Get the current ComfyUI queue: running prompts and pending items."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_history",
        "description": (
            "Get execution history from ComfyUI. Optionally filter by prompt_id. "
            "Returns outputs (images, videos) and execution status."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "prompt_id": {
                    "type": "string",
                    "description": "Specific prompt ID to look up. Omit for recent history.",
                },
                "max_items": {
                    "type": "integer",
                    "description": "Max number of history items to return (default 5).",
                },
            },
            "required": [],
        },
    },
]

# ---------------------------------------------------------------------------
# HTTP helpers
# ---------------------------------------------------------------------------

_TIMEOUT = 15.0


def _get(path: str, timeout: float = _TIMEOUT) -> dict:
    """GET request to ComfyUI, returns parsed JSON.

    Raises httpx.ConnectError or httpx.HTTPStatusError on failure.
    Circuit breaker tracks failures and fast-fails when ComfyUI is down.
    """
    breaker = COMFYUI_BREAKER()
    if not breaker.allow_request():
        raise httpx.ConnectError(
            f"Circuit breaker open — ComfyUI at {COMFYUI_URL} has been unreachable. "
            f"Will retry in {breaker.recovery_timeout:.0f}s."
        )
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}{path}", timeout=timeout)
            resp.raise_for_status()
            breaker.record_success()
            return resp.json()
    except (httpx.ConnectError, httpx.TimeoutException) as e:
        breaker.record_failure()
        raise httpx.ConnectError(str(e)) from e


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_is_running() -> str:
    try:
        stats = _get("/system_stats", timeout=5.0)
        devices = stats.get("devices", [])
        gpu = devices[0].get("name", "unknown") if devices else "no GPU detected"
        py_ver = stats.get("system", {}).get("python_version", "unknown")
        return to_json({
            "running": True,
            "url": COMFYUI_URL,
            "gpu": gpu,
            "python": py_ver,
        })
    except Exception as e:
        return to_json({
            "running": False,
            "url": COMFYUI_URL,
            "error": str(e),
        })


def _handle_get_all_nodes(tool_input: dict) -> str:
    cat_filter = (tool_input.get("category_filter") or "").lower()
    name_filter = (tool_input.get("name_filter") or "").lower()
    fmt = tool_input.get("format", "summary")

    all_info = _get("/object_info", timeout=30.0)

    # Apply filters
    filtered_names = []
    for name in sorted(all_info.keys()):
        info = all_info[name]
        cat = (info.get("category") or "").lower()
        if cat_filter and cat_filter not in cat:
            continue
        if name_filter and name_filter not in name.lower():
            continue
        filtered_names.append(name)

    # Format output based on requested detail level
    if fmt == "names_only":
        return to_json({
            "count": len(filtered_names),
            "nodes": filtered_names,
        })

    if fmt == "full":
        nodes = {}
        for name in filtered_names:
            info = all_info[name]
            nodes[name] = {
                "category": info.get("category", ""),
                "display_name": info.get("display_name", name),
                "description": info.get("description", ""),
                "input_types": sorted((info.get("input", {}).get("required", {})).keys()),
                "output_types": info.get("output", []),
            }
        return to_json({"count": len(nodes), "nodes": nodes})

    # Default: summary (name + category + display_name)
    nodes = {}
    for name in filtered_names:
        info = all_info[name]
        nodes[name] = {
            "category": info.get("category", ""),
            "display_name": info.get("display_name", name),
        }
    return to_json({
        "count": len(nodes),
        "nodes": nodes,
        "hint": "Use format='names_only' for smaller response, or get_node_info for details on a specific node.",
    })


def _handle_get_node_info(tool_input: dict) -> str:
    node_type = tool_input["node_type"]
    all_info = _get(f"/object_info/{node_type}", timeout=10.0)

    info = all_info.get(node_type)
    if not info:
        # Try case-insensitive search
        all_nodes = _get("/object_info", timeout=30.0)
        matches = [n for n in all_nodes if n.lower() == node_type.lower()]
        if matches:
            info = all_nodes[matches[0]]
            node_type = matches[0]
        else:
            # Suggest similar names
            # He2025: sort for deterministic suggestion order
            similar = sorted(n for n in all_nodes if node_type.lower() in n.lower())[:10]
            return to_json({
                "error": f"Node type '{node_type}' not found.",
                "similar_nodes": similar,
            })

    return to_json({
        "class_type": node_type,
        "display_name": info.get("display_name", node_type),
        "category": info.get("category", ""),
        "description": info.get("description", ""),
        "input": info.get("input", {}),
        "output": info.get("output", []),
        "output_name": info.get("output_name", []),
        "output_is_list": info.get("output_is_list", []),
    })


def _handle_get_system_stats() -> str:
    stats = _get("/system_stats", timeout=5.0)
    return to_json(stats)


def _handle_get_queue() -> str:
    queue = _get("/queue", timeout=5.0)
    running = queue.get("queue_running", [])
    pending = queue.get("queue_pending", [])
    return to_json({
        "running_count": len(running),
        "pending_count": len(pending),
        "running": [{"prompt_id": r[1]} for r in running] if running else [],
        "pending": [{"prompt_id": p[1]} for p in pending] if pending else [],
    })


def _handle_get_history(tool_input: dict) -> str:
    prompt_id = tool_input.get("prompt_id")
    max_items = tool_input.get("max_items", 5)

    if prompt_id:
        history = _get(f"/history/{prompt_id}", timeout=10.0)
    else:
        history = _get("/history", timeout=10.0)

    # Trim to max_items
    if not prompt_id and len(history) > max_items:
        # History keys are prompt IDs; take most recent
        keys = list(history.keys())[-max_items:]
        history = {k: history[k] for k in keys}

    # Summarize outputs
    result = {}
    # He2025: sort for deterministic output order
    for pid, entry in sorted(history.items()):
        outputs_summary = []
        for node_id, node_out in sorted(entry.get("outputs", {}).items()):
            for img in node_out.get("images", []):
                outputs_summary.append({
                    "type": "image",
                    "filename": img.get("filename"),
                })
            for vid in node_out.get("gifs", []):
                outputs_summary.append({
                    "type": "video",
                    "filename": vid.get("filename"),
                })
        status_info = entry.get("status", {})
        result[pid] = {
            "status": status_info.get("status_str", "unknown"),
            "completed": status_info.get("completed", False),
            "outputs": outputs_summary,
        }

    return to_json(result)


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a comfy_api tool call."""
    try:
        if name == "is_comfyui_running":
            return _handle_is_running()
        elif name == "get_all_nodes":
            return _handle_get_all_nodes(tool_input)
        elif name == "get_node_info":
            return _handle_get_node_info(tool_input)
        elif name == "get_system_stats":
            return _handle_get_system_stats()
        elif name == "get_queue_status":
            return _handle_get_queue()
        elif name == "get_history":
            return _handle_get_history(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except httpx.ConnectError:
        return to_json({
            "error": f"Could not connect to ComfyUI at {COMFYUI_URL}. Is it running?",
        })
    except httpx.HTTPStatusError as e:
        return to_json({
            "error": f"HTTP {e.response.status_code}: {e.response.text[:200]}",
        })
    except Exception as e:
        return to_json({"error": str(e)})

